import { STAGES } from "./constants";

export type Dashboard2StageId = (typeof STAGES)[number]["id"];

export type StageTransitionReason =
  | "assign_closer"
  | "positive_contact"
  | "meeting_booked"
  | "meeting_completed"
  | "proposal_sent"
  | "proposal_accepted"
  | "stage_changed";

export interface StageTransitionArgs {
  fromStageId: string;
  toStageId: string;
  reason?: StageTransitionReason;
}

export interface StageTransitionCelebrationPayload {
  id: string;
  fromStageId: Dashboard2StageId;
  toStageId: Dashboard2StageId;
  reason: StageTransitionReason;
  title: string;
  subtitle: string;
  nextCue: string;
  fromLabel: string;
  toLabel: string;
  fromColor: string;
  toColor: string;
  confetti: boolean;
}

function isDashboard2StageId(value: string): value is Dashboard2StageId {
  return STAGES.some((s) => s.id === value);
}

function copyForReason(
  reason: StageTransitionReason,
  toName: string,
): Pick<StageTransitionCelebrationPayload, "title" | "subtitle" | "nextCue"> {
  switch (reason) {
    case "assign_closer":
      return {
        title: "Responsável definido",
        subtitle: `O lead entrou em ${toName}.`,
        nextCue: "Registre cada tentativa de contato para manter o funil e o histórico alinhados.",
      };
    case "positive_contact":
      return {
        title: "Qualificação avançou",
        subtitle: `Próximo passo: ${toName}.`,
        nextCue: "Abra o registro de atividades e agende reunião/call com data e formato.",
      };
    case "meeting_booked":
      return {
        title: "Reunião/call confirmada",
        subtitle: `Etapa atual: ${toName}.`,
        nextCue: "Revise a tarefa operacional criada e prepare materiais para o compromisso.",
      };
    case "meeting_completed":
      return {
        title: "Reunião concluída",
        subtitle: `O lead avançou para ${toName}.`,
        nextCue: "Use o contexto comercial da proposta para preparar o próximo envio ao credor.",
      };
    case "proposal_sent":
      return {
        title: "Negociação iniciada",
        subtitle: `O lead avançou para ${toName}.`,
        nextCue: "Acompanhe temperatura, observações e próximos contatos no histórico da proposta.",
      };
    case "proposal_accepted":
      return {
        title: "Proposta aceita",
        subtitle: `O lead avançou para ${toName}.`,
        nextCue: "Comece a coleta de documentos e mantenha as pendências do cedente atualizadas.",
      };
    case "stage_changed":
      return {
        title: "Etapa atualizada",
        subtitle: `O lead avançou para ${toName}.`,
        nextCue: "Revise o próximo passo operacional para manter o funil atualizado.",
      };
  }
}

export function buildStageTransitionCelebrationPayload(params: StageTransitionArgs): StageTransitionCelebrationPayload | null {
  if (!isDashboard2StageId(params.fromStageId) || !isDashboard2StageId(params.toStageId)) return null;
  if (params.fromStageId === params.toStageId) return null;

  const from = STAGES.find((s) => s.id === params.fromStageId)!;
  const to = STAGES.find((s) => s.id === params.toStageId)!;
  const reason = params.reason ?? "stage_changed";
  const { title, subtitle, nextCue } = copyForReason(reason, to.name);

  return {
    id: `${Date.now()}-${params.toStageId}`,
    fromStageId: params.fromStageId,
    toStageId: params.toStageId,
    reason,
    title,
    subtitle,
    nextCue,
    fromLabel: from.short,
    toLabel: to.short,
    fromColor: from.color,
    toColor: to.color,
    confetti: true,
  };
}

export function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function fireStageTransitionConfetti(
  rootEl: HTMLElement | null,
  colors: string[],
): void {
  if (prefersReducedMotion() || !rootEl || typeof window === "undefined") return;
  void import("canvas-confetti").then((mod) => {
    const confetti = mod.default;
    const rect = rootEl.getBoundingClientRect();
    const x = (rect.left + rect.width / 2) / window.innerWidth;
    const y = (rect.top + Math.min(48, rect.height / 3)) / window.innerHeight;
    const palette = colors.length ? colors : ["#38bdf8", "#4f6df5", "#ffffff"];
    void confetti({
      particleCount: 42,
      spread: 58,
      startVelocity: 28,
      ticks: 120,
      gravity: 0.95,
      scalar: 0.9,
      origin: { x, y },
      colors: palette,
    });
  });
}

