'use client';

import type { CSSProperties } from 'react';
import { animated, useSpring } from '@react-spring/web';
import type { LucideIcon } from 'lucide-react';
import {
  AlertCircle,
  AlertTriangle,
  Archive,
  Ban,
  BarChart3,
  Briefcase,
  Building2,
  Calendar,
  CalendarClock,
  Check,
  CheckCircle2,
  Circle,
  ClipboardList,
  Copy,
  FileStack,
  FileText,
  Flame,
  Frown,
  Gavel,
  Ghost,
  Globe,
  Handshake,
  Heart,
  HelpCircle,
  Home,
  Inbox,
  Info,
  Loader2,
  Mail,
  Meh,
  MessageCircle,
  Paperclip,
  Phone,
  PhoneOff,
  RefreshCw,
  Rocket,
  Scale,
  ScrollText,
  Search,
  Send,
  Smile,
  Snowflake,
  SunMedium,
  Target,
  ThumbsUp,
  Timer,
  TrendingDown,
  Trophy,
  Upload,
  User,
  Users,
  UserRound,
  Video,
  Wallet,
  XCircle,
} from 'lucide-react';
import { prefersReducedMotion } from './stage-transition-feedback';

const stageIconMap: Record<string, LucideIcon> = {
  lead: Inbox,
  tentativa: Phone,
  contato: MessageCircle,
  reuniao_ag: CalendarClock,
  reuniao: Send,
  proposta: FileText,
  documentacao: FileStack,
  juridico: Scale,
  cessao: Trophy,
  proposta_aceita: CheckCircle2,
};

export function FunnelStageLucide({
  stageId,
  size = 14,
  color,
  style,
  className,
}: {
  stageId: string;
  size?: number;
  color?: string;
  style?: CSSProperties;
  className?: string;
}) {
  const Icon = stageIconMap[stageId] ?? Inbox;
  return (
    <Icon
      size={size}
      strokeWidth={2}
      className={className}
      style={{ ...style, ...(color ? { color } : {}) }}
      aria-hidden
    />
  );
}

const motivoIconMap: Record<string, LucideIcon> = {
  recusou: XCircle,
  concorrente: TrendingDown,
  desistiu: Ban,
  invalido: AlertTriangle,
  duplicado: Copy,
  sem_contato: PhoneOff,
  reprovado_juridico: Gavel,
  desistiu_docs: FileStack,
};

export function MotivoArquivoLucide({
  motivoKey,
  size = 12,
  color,
}: {
  motivoKey: string;
  size?: number;
  color?: string;
}) {
  const Icon = motivoIconMap[motivoKey] ?? Archive;
  return <Icon size={size} strokeWidth={2} style={{ color }} aria-hidden />;
}

const tempIconMap: Record<string, LucideIcon> = {
  hot: Flame,
  warm: SunMedium,
  cold: Snowflake,
};

const tempIconColor: Record<string, string> = {
  hot: '#dc2626',
  warm: '#d97706',
  cold: '#64748b',
};

export function TempLucide({
  temp,
  size = 12,
  animatedIcon = false,
}: {
  temp: string;
  size?: number;
  animatedIcon?: boolean;
}) {
  const shouldReduceMotion = prefersReducedMotion();
  const Icon = tempIconMap[temp] ?? Snowflake;
  const color = tempIconColor[temp] ?? tempIconColor.cold;

