"use client";

import type { CSSProperties } from "react";
import { useState } from "react";
import { animated, useSpring } from "@react-spring/web";
import { TempLucide } from "../dashboard2-lucide";
import { prefersReducedMotion } from "../stage-transition-feedback";

type TemperatureId = "hot" | "warm" | "cold";

interface TemperatureBadgeProps {
  temp?: string | null;
  label?: string;
  active?: boolean;
  interactive?: boolean;
  compact?: boolean;
  iconOnly?: boolean;
  className?: string;
  style?: CSSProperties;
}

const temperatureTheme: Record<TemperatureId, {
  label: string;
  color: string;
  border: string;
  background: string;
  glow: string;
}> = {
  hot: {
    label: "Quente",
    color: "#dc2626",
    border: "#fecaca",
    background: "linear-gradient(135deg, #fff7ed 0%, #fef2f2 52%, #fee2e2 100%)",
    glow: "rgba(220,38,38,0.22)",
  },
  warm: {
    label: "Morno",
    color: "#d97706",
    border: "#fde68a",
    background: "linear-gradient(135deg, #fffbeb 0%, #fef3c7 55%, #fff7ed 100%)",
    glow: "rgba(217,119,6,0.2)",
  },
  cold: {
    label: "Frio",
    color: "#64748b",
    border: "#cbd5e1",
    background: "linear-gradient(135deg, #f8fafc 0%, #f1f5f9 58%, #e0f2fe 100%)",
    glow: "rgba(100,116,139,0.16)",
  },
};

function normalizeTemperature(temp?: string | null): TemperatureId {
  if (temp === "hot" || temp === "warm" || temp === "cold") return temp;
  return "cold";
}

export function TemperatureBadge({
  temp,
  label,
  active = false,
  interactive = false,
  compact = false,
  iconOnly = false,
  className,
  style,
}: TemperatureBadgeProps) {
  const [isHovering, setIsHovering] = useState(false);
