    config: { tension: 420, friction: 24, mass: 0.68 },
    immediate: shouldReduceMotion,
  });

  return (
    <animated.span
      className={className}
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => setIsHovering(false)}
      style={{
        ...badgeSpring,
