interface StageTransitionCelebrationProps {
  payload: StageTransitionCelebrationPayload | null;
  onDismiss: () => void;
  autoDismissMs?: number;
}

export function StageTransitionCelebration({
  payload,
  onDismiss,
  autoDismissMs = 4800,
}: StageTransitionCelebrationProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const dismissedRef = useRef(false);
  const shouldReduceMotion = prefersReducedMotion();
  const transitions = useTransition(payload, {
    from: {
      opacity: 0,
      transform: shouldReduceMotion ? "translate3d(0px,0px,0px) scale(1)" : "translate3d(0px,-14px,0px) scale(0.97)",
    },
    enter: {
      opacity: 1,
      transform: "translate3d(0px,0px,0px) scale(1)",
    },
    leave: {
      opacity: 0,
      transform: shouldReduceMotion ? "translate3d(0px,0px,0px) scale(1)" : "translate3d(0px,-8px,0px) scale(0.985)",
    },
    config: {
      tension: 420,
      friction: 28,
      mass: 0.82,
    },
    immediate: shouldReduceMotion,
