/** Pure proximity math for sidebar micro-interaction (Line Sidebar idea, Celer-restrained). */

export const SIDEBAR_PROXIMITY_RADIUS_PX = 72;
/** Plan Fase 5: hover / proximity shift ≤ 2px. */
export const SIDEBAR_PROXIMITY_MAX_SHIFT_PX = 2;
export const SIDEBAR_PROXIMITY_VAR_SHIFT = '--sidebar-prox-shift';
export const SIDEBAR_PROXIMITY_VAR_STRENGTH = '--sidebar-prox';
export const SIDEBAR_PROXIMITY_TARGET_SELECTOR =
    '[data-sidebar="menu-button"], [data-sidebar="menu-sub-button"]';

/**
 * Maps vertical distance from cursor to item center into 0..1.
 * Uses smoothstep falloff (React Bits "smooth" idea without copying the component).
 */
export function proximityStrength(
    distancePx: number,
    radiusPx: number = SIDEBAR_PROXIMITY_RADIUS_PX,
): number {
    if (radiusPx <= 0 || distancePx >= radiusPx) return 0;
    if (distancePx <= 0) return 1;
    const t = 1 - distancePx / radiusPx;
    return t * t * (3 - 2 * t);
}

export function proximityShiftPx(
    strength: number,
    maxShiftPx: number = SIDEBAR_PROXIMITY_MAX_SHIFT_PX,
): number {
    if (maxShiftPx <= 0 || strength <= 0) return 0;
    const clamped = Math.min(1, Math.max(0, strength));
    return clamped * maxShiftPx;
}

export function prefersReducedMotion(): boolean {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
        return false;
    }
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

export function clearSidebarProximityStyles(root: ParentNode): void {
    root.querySelectorAll<HTMLElement>(SIDEBAR_PROXIMITY_TARGET_SELECTOR).forEach((el) => {
        el.style.removeProperty(SIDEBAR_PROXIMITY_VAR_SHIFT);
        el.style.removeProperty(SIDEBAR_PROXIMITY_VAR_STRENGTH);
    });
}

