import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils';
import { withAlpha } from '@/design-system';

/** Margem em px para habilitar setas nas pontas do carrossel. */
const CAROUSEL_SCROLL_EDGE_PX = 6;

type DocumentsStageCarouselNavProps = {
    children: ReactNode;
    accentColor: string;
    className?: string;
};

function prefersReducedMotion(): boolean {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

export function DocumentsStageCarouselNav({
    children,
    accentColor,
    className,
}: DocumentsStageCarouselNavProps) {
    const scrollerRef = useRef<HTMLDivElement>(null);
    const [current, setCurrent] = useState(0);
    const [count, setCount] = useState(0);
    const [canPrev, setCanPrev] = useState(false);
    const [canNext, setCanNext] = useState(false);

    const sync = useCallback(() => {
        const el = scrollerRef.current;
        if (!el) return;

        const kids = Array.from(el.children) as HTMLElement[];
        setCount(kids.length);

        if (kids.length === 0) {
            setCurrent(0);
            setCanPrev(false);
            setCanNext(false);
            return;
        }

        const mid = el.scrollLeft + el.clientWidth / 2;
        let best = 0;
        let bestDist = Number.POSITIVE_INFINITY;
        kids.forEach((child, index) => {
            const center = child.offsetLeft + child.offsetWidth / 2;
            const dist = Math.abs(center - mid);
            if (dist < bestDist) {
                bestDist = dist;
                best = index;
            }
        });

        setCurrent(best);
        setCanPrev(el.scrollLeft > CAROUSEL_SCROLL_EDGE_PX);
        setCanNext(el.scrollLeft + el.clientWidth < el.scrollWidth - CAROUSEL_SCROLL_EDGE_PX);
    }, []);

    useEffect(() => {
        const el = scrollerRef.current;
        if (!el) return;

        sync();
        el.addEventListener('scroll', sync, { passive: true });
        const ro = new ResizeObserver(sync);
        ro.observe(el);

        return () => {
            el.removeEventListener('scroll', sync);
            ro.disconnect();
        };
    }, [sync, children]);

    const scrollToIndex = useCallback((index: number) => {
        const el = scrollerRef.current;
        if (!el) return;
        const child = el.children[index] as HTMLElement | undefined;
        if (!child) return;
        child.scrollIntoView({
            behavior: prefersReducedMotion() ? 'auto' : 'smooth',
            inline: 'center',
            block: 'nearest',
        });
    }, []);

    const showNav = count > 1;
    const arrowStyle = {
        color: accentColor,
        borderColor: withAlpha(accentColor, 0.35),
        backgroundColor: withAlpha(accentColor, 0.08),
    };

    return (
        <div className={cn('min-w-0', className)}>
            <div

