import { type ReactNode } from "react";
import { Pin, UserRound } from "lucide-react";
import { animated, useSpring, useTransition } from "@react-spring/web";
import { Sheet, SheetContent, SheetOverlay, SheetPortal } from "@/components/ui/sheet";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import LeadDetailHeader from "./LeadDetailHeader";
import { LeadDetailPopups } from "./LeadDetailPopups";
import { StageTransitionCelebration } from "./StageTransitionCelebration";
import { AccordionPanelContent } from "../page";
import { prefersReducedMotion, type StageTransitionArgs, type StageTransitionCelebrationPayload } from "../stage-transition-feedback";
import { LeadTasksPanel } from "./LeadTasksPanel";
import { B2CLeadInternalPanel } from "./b2c/B2CLeadInternalPanel";
import { sendToastMessage } from "@/functions/messages/toastMessage";
import { deleteDocument } from "@/services/BrokerServices";
import { d2 } from "../dashboard2-tw";
import { cn } from "@/lib/utils";

function AnimatedSheetTab({
  isActive,
  variant,
  children,
  onClick,
  className,
}: {
  isActive: boolean;
  variant: "lead" | "tarefas";
  children: ReactNode;
  onClick: () => void;
  className: string;
}) {
  const shouldReduceMotion = prefersReducedMotion();
  const tabSpring = useSpring({
    transform: isActive && !shouldReduceMotion ? "translate3d(0px,-1px,0px)" : "translate3d(0px,0px,0px)",
    opacity: isActive ? 1 : 0.82,
    config: { tension: 420, friction: 26, mass: 0.7 },
    immediate: shouldReduceMotion,
  });
  const iconSpring = useSpring({
    transform: isActive && !shouldReduceMotion ? "scale(1.08) rotate(-3deg)" : "scale(1) rotate(0deg)",
    config: { tension: 460, friction: 22, mass: 0.65 },
    immediate: shouldReduceMotion,
  });
  const Icon = variant === "lead" ? UserRound : Pin;

  return (
    <animated.button type="button" onClick={onClick} className={className} style={tabSpring}>
      <animated.span style={{ ...iconSpring, display: "inline-flex", flexShrink: 0 }}>
        <Icon size={13} strokeWidth={2.5} aria-hidden />
      </animated.span>
      {children}

