import { expect } from '@jest/globals';
import {
    SIDEBAR_PROXIMITY_MAX_SHIFT_PX,
    SIDEBAR_PROXIMITY_RADIUS_PX,
    SIDEBAR_PROXIMITY_VAR_SHIFT,
    SIDEBAR_PROXIMITY_VAR_STRENGTH,
    applySidebarProximityFromPointer,
    clearSidebarProximityStyles,
    prefersReducedMotion,
    proximityShiftPx,
    proximityStrength,
} from '@/components/Sidebar/sidebar-proximity';
import {
    sidebarInstrumentPanelClass,
    sidebarNavGroupLabel,
    sidebarNavItemActive,
    sidebarNavItemClass,
    sidebarNavItemInteractive,
    sidebarNavParentActive,
    sidebarNavSubMenuButton,
    sidebarNavTransition,
    sidebarSignupButtonClass,
    sidebarVisitorItemClass,
} from '@/components/Sidebar/sidebar-nav-styles';

describe('sidebar proximity (Fase 5)', () => {
    it('returns full strength at the item center', () => {
        expect(proximityStrength(0)).toBe(1);
    });

    it('returns zero at and beyond the radius', () => {
        expect(proximityStrength(SIDEBAR_PROXIMITY_RADIUS_PX)).toBe(0);
        expect(proximityStrength(SIDEBAR_PROXIMITY_RADIUS_PX + 10)).toBe(0);
    });

    it('uses smooth falloff between center and radius', () => {
        const mid = proximityStrength(SIDEBAR_PROXIMITY_RADIUS_PX / 2);
        expect(mid).toBeGreaterThan(0);
        expect(mid).toBeLessThan(1);
        expect(proximityStrength(SIDEBAR_PROXIMITY_RADIUS_PX / 4)).toBeGreaterThan(mid);
    });

    it('caps horizontal shift at 2px (plan budget)', () => {
        expect(SIDEBAR_PROXIMITY_MAX_SHIFT_PX).toBe(2);
        expect(proximityShiftPx(1)).toBe(2);
        expect(proximityShiftPx(0.5)).toBe(1);
        expect(proximityShiftPx(0)).toBe(0);
        expect(proximityShiftPx(2)).toBe(2);
    });
});

describe('applySidebarProximityFromPointer', () => {
    function makeButton(top: number, height = 32) {
        const el = document.createElement('button');
        el.setAttribute('data-sidebar', 'menu-button');
        el.getBoundingClientRect = () =>
            ({
                top,
                bottom: top + height,
                height,
                width: 200,
                left: 0,
                right: 200,
                x: 0,
                y: top,
                toJSON: () => ({}),
            }) as DOMRect;
        return el;
    }

    it('sets CSS vars on the nearest item and clears distant ones', () => {
        const root = document.createElement('div');
        const near = makeButton(100);
        const far = makeButton(400);
        root.append(near, far);

        applySidebarProximityFromPointer(root, 116);

        expect(near.style.getPropertyValue(SIDEBAR_PROXIMITY_VAR_STRENGTH)).not.toBe('');
        expect(near.style.getPropertyValue(SIDEBAR_PROXIMITY_VAR_SHIFT)).toMatch(/px$/);
        expect(far.style.getPropertyValue(SIDEBAR_PROXIMITY_VAR_STRENGTH)).toBe('');
    });

    it('clearSidebarProximityStyles removes vars', () => {
        const root = document.createElement('div');
        const el = makeButton(40);
        root.append(el);
        applySidebarProximityFromPointer(root, 56);
        clearSidebarProximityStyles(root);
        expect(el.style.getPropertyValue(SIDEBAR_PROXIMITY_VAR_SHIFT)).toBe('');
        expect(el.style.getPropertyValue(SIDEBAR_PROXIMITY_VAR_STRENGTH)).toBe('');
    });
});

describe('sidebar-nav-styles Fase 5 polish', () => {
    it('active item uses fill + ring + icon tint without left-bar slop', () => {
        expect(sidebarNavItemActive).toContain('ring-1');
        expect(sidebarNavItemActive).toContain('[&_svg]:text-(--celer-blue)');
        expect(sidebarNavItemActive).not.toContain('inset_2px');
        expect(sidebarNavItemActive).not.toContain('border-l');
        expect(sidebarNavParentActive).not.toContain('inset_2px');
    });

    it('interactive surface uses Ôëñ2px prox/hover shift and reduced-motion off', () => {
        expect(sidebarNavItemInteractive).toContain('--sidebar-prox-shift');
        expect(sidebarNavItemInteractive).toContain('2px');
        expect(sidebarNavItemInteractive).toContain('motion-reduce:transform-none');
        expect(sidebarNavTransition).toContain('transform');
        expect(sidebarNavTransition).toContain('duration-200');
        expect(sidebarNavTransition).toContain('motion-reduce:transition-none');
    });

    it('sidebarNavItemClass composes interactive + active', () => {
        expect(sidebarNavItemClass(false)).toContain('--sidebar-prox-shift');
        expect(sidebarNavItemClass(false)).not.toContain('[&_svg]');
        expect(sidebarNavItemClass(true)).toContain('[&_svg]:text-(--celer-blue)');
        expect(sidebarNavItemClass(true)).toContain('--sidebar-prox-shift');
    });

    it('exports group label chrome and nested submenu surface', () => {
        expect(sidebarNavGroupLabel).toContain('uppercase');
        expect(sidebarNavGroupLabel).toContain('text-(--text-muted)');
        expect(sidebarNavSubMenuButton).toContain('--sidebar-prox-shift');
    });

    it('visitor chrome reuses the paper instrument of the mesa', () => {
        expect(sidebarInstrumentPanelClass).toContain('from-white via-celer-paper');
        expect(sidebarInstrumentPanelClass).toContain('inset_0_1px_0');
        expect(sidebarVisitorItemClass(true)).toContain('liquid-instrument-facet');
        expect(sidebarVisitorItemClass(true)).toContain('[&_svg]:text-(--celer-blue)');
        expect(sidebarSignupButtonClass).toContain('liquid-instrument-facet');
    });
});

describe('prefersReducedMotion', () => {
    const originalMatchMedia = window.matchMedia;

    afterEach(() => {
        window.matchMedia = originalMatchMedia;
    });

    it('reads prefers-reduced-motion media query', () => {
        window.matchMedia = jest.fn().mockImplementation((query: string) => ({
            matches: query.includes('prefers-reduced-motion'),
            media: query,
            onchange: null,
            addListener: jest.fn(),
            removeListener: jest.fn(),
            addEventListener: jest.fn(),
            removeEventListener: jest.fn(),
            dispatchEvent: jest.fn(),
        }));
        expect(prefersReducedMotion()).toBe(true);
    });
});

