function calcLeadScore(lead) {
  let score = 0;
  const v = lead.valorPrecatorio || 0;
  if (v >= 300000) score += 40; else if (v >= 150000) score += 30; else if (v >= 50000) score += 20; else score += 10;
  const tc = lead.tipoCredito || lead.tipo;
  if (tc === "Precatório" || tc === "Alimentar") score += 25; else if (tc === "Creditório" || tc === "Comum") score += 15; else score += 10;
  const tr = lead.tribunal || "";
  if (["TRF-3", "TRF-1"].includes(tr)) score += 20; else if (["TRF-2", "TRF-4"].includes(tr)) score += 15; else score += 10;
  if (lead.telefone && lead.email) score += 15; else if (lead.telefone || lead.email) score += 8;
  return Math.min(score, 100);
}
function leadScoreStyle(s) {
  if (s >= 75) return { color: "#059669", bg: "#ecfdf5", label: "Alto" };
  if (s >= 50) return { color: "#d97706", bg: "#fffbeb", label: "Médio" };
  return { color: "#dc2626", bg: "#fef2f2", label: "Baixo" };
}

