function getLeadActivities(lead, stageFilter) {
  const a = [];
  let nextId = 0;
  /* System events */
  if (lead.dataEntrada) a.push({ id: nextId++, canal: "Sistema", resultado: "Lead captado", data: lead.dataEntrada, agente: "Sistema", nota: "Via " + (lead.captacao || "\u2014"), contatoUsado: "", stage: "lead" });
  /* All tentativas (regardless of stage) */
  (lead.tentativas || []).forEach(t => {
    a.push({
      id: nextId++,
      canal: t.canal,
      resultado: t.resultado,
      data: t.data,
      agente: t.agente || lead.sdr || "SDR",
      nota: t.nota || "",
      contatoUsado: t.contatoUsado || "",
      stage: t.stage || null,
      dotColor: t.dotColor,
    });
  });
  /* Primeiro contato */
  if (lead.dataPrimeiroContato) a.push({ id: nextId++, canal: lead.formatoContato || "Liga\u00e7\u00e3o", resultado: "Contato realizado", data: lead.dataPrimeiroContato, agente: lead.sdr || "SDR", nota: lead.primeiroAtendimento || "", contatoUsado: lead.primeiroContatoInfo || "", stage: "contato" });
  /* Reuniao */
  if (lead.reuniaoRealizada) a.push({ id: nextId++, canal: "Videocall", resultado: "Realizada", data: lead.reuniaoRealizada, agente: lead.closer || "Closer", nota: lead.resumoReuniao ? lead.resumoReuniao.slice(0, 80) : "", contatoUsado: "", stage: "reuniao_ag" });
  if (lead.propostaValor) a.push({ id: nextId++, canal: "Sistema", resultado: "Proposta", data: lead.reuniaoRealizada || lead.dataEntrada, agente: lead.closer || "Closer", nota: "R$ " + (lead.propostaValor || 0).toLocaleString("pt-BR"), contatoUsado: "", stage: "reuniao" });
  /* Follow-ups */
  (lead.followups || []).forEach(f => {
    a.push({ id: nextId++, canal: "WhatsApp", resultado: f.status === "done" ? "Conclu\u00eddo" : "Pendente", data: f.data, agente: lead.sdr || "SDR", nota: f.interacao || "", contatoUsado: "", stage: f.stage || "proposta" });
  });
  if (stageFilter) return a.filter(act => act.stage === stageFilter);
  return a;
}





